/**
 * Remove time-of-day from <omo-env> block in system prompts.
 * Keeps date/timezone/locale intact for context, only strips the
 * "Current time" line which changes every request and kills cache hits.
 *
 * @type {import('@opencode-ai/plugin').Plugin}
 */
export const OmoNoTime = async (_ctx) => {
  const CURRENT_TIME_LINE_RE = /^\s*Current time:.*\n?/gm

  return {
    "experimental.chat.system.transform": async (_input, output) => {
      for (let i = 0; i < output.system.length; i++) {
        const segment = output.system[i]
        if (typeof segment !== "string") continue

        output.system[i] = segment
          .replace(CURRENT_TIME_LINE_RE, "")
          .replace(/\n{3,}/g, "\n\n")
          .trim()
      }
    },
  }
}
